import type { CardImage } from '@/types';

/** Widths generated by scripts/optimize-images.mjs at build time. Keep in sync. */
const WIDTHS = [480, 960, 1440];

/** Resized WebP copies only exist in production builds; the dev server serves the originals. */
export const hasResponsiveImages = import.meta.env.PROD;

export const originalSrc = (image: CardImage) => `/assets/${image.name}.${image.png ? 'png' : 'jpg'}`;

export const webpSrcset = (image: CardImage) => WIDTHS.map((width) => `/assets/${image.name}-${width}.webp ${width}w`).join(', ');

/** How wide each kind of card image is drawn, so the browser picks the smallest file that is sharp enough. */
export const IMAGE_SIZES = {
  project: '(min-width: 1280px) 580px, (min-width: 1024px) 46vw, 94vw',
  article: '(min-width: 1280px) 400px, (min-width: 1024px) 31vw, 94vw',
  drawer: '(min-width: 768px) 640px, 100vw',
};
